const body = $json.body || $json;
const theme = body.theme || '品質教育動画';
const source = body.source || '';
const duration = body.duration || '60秒';
const prompt = `あなたは製造業QA教育動画の専門ディレクターです。${duration}の動画を作成してください。テーマ：${theme}。元情報：${source}。顧客名・品番・図番・個人情報は出さず、原因未確定の事項は断定しない。構成は、問題提起、現象説明、原因候補、確認方法、対策、まとめ。日本語字幕と日本語ナレーション。`;
return [{json:{theme, duration, topview_prompt: prompt, mode: 'manual_or_api_stub'}}];

